"use client"

/**
 * Lazy registry for Lucide icons (stable + experimental) used by the
 * "system" group of the Add-Icon modal and by IconNode glyphs.
 *
 * - Stable icons come from `lucide-react`'s `icons` export (loaded lazily so
 *   the ~1600 components never enter the initial bundle).
 * - Experimental icons come from `@lucide/lab`.
 * - Categories / tags / aliases come from /lucide-meta.json (generated by
 *   scripts/gen-lucide-meta.mjs from the lucide-icons/lucide repo).
 */

import type { ComponentType, SVGProps } from "react"

export type LucideIconComp = ComponentType<
  SVGProps<SVGSVGElement> & { size?: number | string; strokeWidth?: number | string }
>

export type LucideEntry = {
  /** kebab-case name, e.g. "a-arrow-down" */
  name: string
  comp: LucideIconComp
  cats: string[]
  tags: string[]
  aliases: string[]
  experimental: boolean
}

export type LucideGroup = {
  slug: string
  title: string
  entries: LucideEntry[]
}

export type LucideRegistry = {
  groups: LucideGroup[]
  byName: Map<string, LucideEntry>
  byAlias: Map<string, string>
  total: number
}

type MetaFile = {
  version: string
  categories: { slug: string; title: string }[]
  icons: Record<string, { c?: string[]; t?: string[]; a?: string[] }>
}

let registryPromise: Promise<LucideRegistry> | null = null

function pascalToKebab(s: string): string {
  return s
    .replace(/([a-z0-9])([A-Z])/g, "$1-$2")
    .replace(/([A-Z])([A-Z][a-z])/g, "$1-$2")
    .toLowerCase()
}

function camelToKebab(s: string): string {
  return s.replace(/([a-z0-9])([A-Z])/g, "$1-$2").toLowerCase()
}

export function loadLucideRegistry(): Promise<LucideRegistry> {
  if (!registryPromise) {
    registryPromise = buildRegistry().catch((err) => {
      // Allow a later retry if something (e.g. network) failed.
      registryPromise = null
      throw err
    })
  }
  return registryPromise
}

async function buildRegistry(): Promise<LucideRegistry> {
  const [lucideMod, meta, lab] = await Promise.all([
    import("lucide-react"),
    fetch("/lucide-meta.json").then((r) => {
      if (!r.ok) throw new Error(`failed to load lucide metadata (${r.status})`)
      return r.json() as Promise<MetaFile>
    }),
    import("@lucide/lab")
      .then((m) => m as unknown as Record<string, unknown>)
      .catch(() => ({}) as Record<string, unknown>),
  ])

  const icons = lucideMod.icons as unknown as Record<string, LucideIconComp>
  // @lucide/lab ships raw IconNode arrays — wrap them into real components
  const createIconNode = lucideMod.createLucideIcon as unknown as
    | ((iconName: string, iconNode: unknown) => LucideIconComp)
    | undefined

  const titleBySlug = new Map(meta.categories.map((c) => [c.slug, c.title] as const))
  const buckets = new Map<string, LucideEntry[]>()
  const byName = new Map<string, LucideEntry>()
  const byAlias = new Map<string, string>()

  const pushToBucket = (slug: string, entry: LucideEntry) => {
    const normalized = titleBySlug.has(slug) ? slug : "other"
    let list = buckets.get(normalized)
    if (!list) {
      list = []
      buckets.set(normalized, list)
    }
    list.push(entry)
  }

  // Stable icons shipped by lucide-react
  // NOTE: lucide icons are ForwardRefExoticComponent objects (not plain functions)
  for (const [pascalName, comp] of Object.entries(icons)) {
    if (!comp) continue
    const name = pascalToKebab(pascalName)
    if (!name || byName.has(name)) continue
    const metaIcon = meta.icons[name]
    const entry: LucideEntry = {
      name,
      comp,
      cats: metaIcon?.c?.length ? metaIcon.c : ["other"],
      tags: (metaIcon?.t ?? []).filter((t): t is string => typeof t === "string"),
      aliases: (metaIcon?.a ?? []).filter((a): a is string => typeof a === "string"),
      experimental: false,
    }
    byName.set(name, entry)
    for (const alias of entry.aliases) {
      if (!byAlias.has(alias)) byAlias.set(alias, name)
    }
    for (const cat of entry.cats) pushToBucket(cat, entry)
  }

  // Experimental icons from @lucide/lab (exports are camelCase, sometimes Icon-prefixed;
  // values are raw IconNode arrays that need createLucideIcon wrapping)
  const experimental: LucideEntry[] = []
  for (const [rawKey, node] of Object.entries(lab)) {
    if (!node || !Array.isArray(node)) continue
    if (!createIconNode) break
    const base = rawKey.startsWith("Icon") ? rawKey.slice(4) : rawKey
    const name = camelToKebab(base)
    if (!name || byName.has(name)) continue
    const entry: LucideEntry = {
      name,
      comp: createIconNode(name, node),
      cats: ["experimental"],
      tags: [],
      aliases: [],
      experimental: true,
    }
    byName.set(name, entry)
    experimental.push(entry)
  }

  const groups: LucideGroup[] = []
  for (const cat of meta.categories) {
    const entries = buckets.get(cat.slug)
    if (entries && entries.length > 0) {
      groups.push({ slug: cat.slug, title: cat.title, entries })
    }
  }
  const other = buckets.get("other")
  if (other && other.length > 0) {
    groups.push({ slug: "other", title: "Other", entries: other })
  }
  if (experimental.length > 0) {
    groups.push({ slug: "experimental", title: "Experimental", entries: experimental })
  }

  return { groups, byName, byAlias, total: byName.size }
}

/** Resolve a kebab-case name (or old alias like "home") to its icon entry. */
export async function getLucideEntry(name: string): Promise<LucideEntry | null> {
  try {
    const reg = await loadLucideRegistry()
    return reg.byName.get(name) ?? reg.byName.get(reg.byAlias.get(name) ?? "") ?? null
  } catch {
    return null
  }
}
